@Ioo_mem_nhdsLT : ∀ {α : Type u_1} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [ClosedIicTopology α] {a b : α},
  a < b → Set.Ioo a b ∈ nhdsWithin b (Set.Iio b)
@Ioo_mem_nhdsLT_of_mem : ∀ {α : Type u_1} [inst : TopologicalSpace α] [inst_1 : LinearOrder α] [ClosedIicTopology α]
  {a b c : α}, b ∈ Set.Ioc a c → Set.Ioo a c ∈ nhdsWithin b (Set.Iio b)
@pow_le_one₀ : ∀ {M₀ : Type u_1} [inst : MonoidWithZero M₀] [inst_1 : Preorder M₀] {a : M₀} [PosMulMono M₀] {n : ℕ},
  0 ≤ a → a ≤ 1 → a ^ n ≤ 1
@Filter.Eventually.of_forall : ∀ {α : Type u_1} {p : α → Prop} {f : Filter α}, (∀ (x : α), p x) → ∀ᶠ (x : α) in f, p x
@tendsto_of_tendsto_of_tendsto_of_le_of_le' : ∀ {α : Type u_1} {β : Type u_2} [ts : TopologicalSpace α]
  [inst : Preorder α] [OrderTopology α] {f g h : β → α} {b : Filter β} {a : α},
  Filter.Tendsto g b (nhds a) →
    Filter.Tendsto h b (nhds a) →
      (∀ᶠ (b : β) in b, g b ≤ f b) → (∀ᶠ (b : β) in b, f b ≤ h b) → Filter.Tendsto f b (nhds a)

